config.chat_template_jinja:
{%- for message in messages if message['role'] == 'system' -%}
{%- for content in message['content'] -%}{{ content['text'] }}{%- endfor -%}
{%- endfor -%}
{%- for message in messages if message['role'] != 'system' -%}
{%- for content in message['content'] if content['type'] == 'image' -%}
{{ '<|vision_start|><|image_pad|><|vision_end|>' }}
{%- endfor -%}
{%- for content in message['content'] if content['type'] == 'text' -%}
{{ content['text'] }}
{%- endfor -%}
{%- endfor -%}

